def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    if n >= 100:
        return 'D'

    opp_last = history[-1][1]
    my_last = history[-1][0]

    if n == 1:
        return 'C' if opp_last == 'C' else 'D'

    if n == 99:
        return 'D'

    recent = history[-10:] if n >= 10 else history
    recent_c = sum(1 for a, b in recent if b == 'C')
    recent_n = len(recent)
    opp_total_c = sum(1 for a, b in history if b == 'C')
    my_total_c = sum(1 for a, b in history if a == 'C')
    opp_rate = opp_total_c / n

    consecutive_opp_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            consecutive_opp_d += 1
        else:
            break

    consecutive_opp_c = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            consecutive_opp_c += 1
        else:
            break

    if n >= 90:
        if opp_rate > 0.5:
            return 'D'
        return 'C'

    if opp_total_c == 0:
        return 'D'

    if opp_total_c == n:
        if n >= 20 and rng.random() < 0.25:
            return 'D'
        return 'C'

    if n >= 20 and opp_rate < 0.1:
        return 'D' if rng.random() < 0.85 else 'C'

    if consecutive_opp_d >= 3:
        if opp_rate > 0.35:
            return 'D'
        if rng.random() < 0.85:
            return 'D'
        return 'C'

    if consecutive_opp_d == 2:
        if recent_c >= 6:
            return 'C'
        return 'D' if rng.random() < 0.8 else 'C'

    if opp_last == 'D':
        if opp_rate > 0.55:
            return 'D' if rng.random() < 0.8 else 'C'
        if recent_c >= 8 and my_last == 'D':
            return 'C'
        if opp_rate < 0.4 and rng.random() < 0.5:
            return 'D'
        return 'D' if rng.random() < 0.7 else 'C'

    if opp_last == 'C':
        if consecutive_opp_c >= 4 and opp_rate > 0.8:
            if rng.random() < 0.15:
                return 'D'
            return 'C'
        if my_last == 'D' and opp_rate > 0.6:
            return 'C'
        if recent_c >= 8:
            return 'C'
        if recent_c <= 4 and opp_rate < 0.5:
            return 'D' if rng.random() < 0.4 else 'C'
        if opp_rate < 0.35:
            return 'D' if rng.random() < 0.5 else 'C'
        return 'C'

    return 'C'
